func (q *Queries) ListStudentViolations(ctx context.Context, arg ListStudentViolationsParams) ([]ListStudentViolationsRow, error) {
	rows, err := q.db.Query(ctx, listStudentViolations,
		arg.AcademicYearID,
		arg.SchoolID,
		arg.StudentID,
		arg.ClassID,
		arg.FromDate,
		arg.ToDate,
		arg.OffsetRows,
		arg.LimitRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListStudentViolationsRow
	for rows.Next() {
		var i ListStudentViolationsRow
		if err := rows.Scan(
			&i.ID,
			&i.OccurredOn,
			&i.Note,
			&i.AttendanceSessionID,
			&i.CreatedAt,
			&i.StudentID,
			&i.StudentName,
			&i.StudentNis,
			&i.ClassName,
			&i.ViolationTypeID,
			&i.ViolationName,
			&i.ViolationPoints,
			&i.NotedBy,
			&i.NotedByName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

