const listViolationsForStudentYear = `-- name: ListViolationsForStudentYear :many
SELECT sv.id, sv.occurred_on, sv.note, sv.attendance_session_id, sv.created_at,
       vt.id AS violation_type_id, vt.name AS violation_name, vt.points AS violation_points,
       sv.noted_by, u.name AS noted_by_name
FROM student_violations sv
JOIN violation_types vt ON vt.id = sv.violation_type_id
JOIN users u ON u.id = sv.noted_by
WHERE sv.school_id = $1 AND sv.academic_year_id = $2 AND sv.student_id = $3
ORDER BY sv.occurred_on, sv.id
`

type ListViolationsForStudentYearParams struct {
	SchoolID       int64 `json:"school_id"`
	AcademicYearID int64 `json:"academic_year_id"`
	StudentID      int64 `json:"student_id"`
}

type ListViolationsForStudentYearRow struct {
	ID                  int64              `json:"id"`
	OccurredOn          pgtype.Date        `json:"occurred_on"`
	Note                string             `json:"note"`
	AttendanceSessionID pgtype.Int8        `json:"attendance_session_id"`
	CreatedAt           pgtype.Timestamptz `json:"created_at"`
	ViolationTypeID     int64              `json:"violation_type_id"`
	ViolationName       string             `json:"violation_name"`
	ViolationPoints     int32              `json:"violation_points"`
	NotedBy             int64              `json:"noted_by"`
	NotedByName         string             `json:"noted_by_name"`
}

