const nextLetterSeq = `-- name: NextLetterSeq :one

INSERT INTO discipline_letter_number_counters (school_id, year, seq) VALUES ($1, $2, 1)
ON CONFLICT (school_id, year) DO UPDATE SET seq = discipline_letter_number_counters.seq + 1
RETURNING seq
`

type NextLetterSeqParams struct {
	SchoolID int64  `json:"school_id"`
	Year     string `json:"year"`
}

// -- nomor surat (counter atomik per sekolah+tahun) --
func (q *Queries) NextLetterSeq(ctx context.Context, arg NextLetterSeqParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextLetterSeq, arg.SchoolID, arg.Year)
	var seq int32
	err := row.Scan(&seq)
	return seq, err
}

const updateViolationType = `-- name: UpdateViolationType :one
UPDATE violation_types SET
    name = COALESCE($1, name),
    points = COALESCE($2, points),
    category = COALESCE($3, category),
    active = COALESCE($4, active)
WHERE id = $5 AND school_id = $6
RETURNING id, school_id, name, points, category, active
`

type UpdateViolationTypeParams struct {
	Name     pgtype.Text `json:"name"`
	Points   pgtype.Int4 `json:"points"`
	Category pgtype.Text `json:"category"`
	Active   pgtype.Bool `json:"active"`
	ID       int64       `json:"id"`
	SchoolID int64       `json:"school_id"`
}

func (q *Queries) UpdateViolationType(ctx context.Context, arg UpdateViolationTypeParams) (ViolationType, error) {
	row := q.db.QueryRow(ctx, updateViolationType,
		arg.Name,
		arg.Points,
		arg.Category,
		arg.Active,
		arg.ID,
		arg.SchoolID,
	)
	var i ViolationType
	err := row.Scan(
		&i.ID,
		&i.SchoolID,
		&i.Name,
		&i.Points,
		&i.Category,
		&i.Active,
	)
	return i, err
}

const upsertSPSettings = `-- name: UpsertSPSettings :one
INSERT INTO discipline_sp_settings (school_id, academic_year_id, sp1, sp2, sp3)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (school_id, academic_year_id) DO UPDATE SET sp1 = $3, sp2 = $4, sp3 = $5
RETURNING school_id, academic_year_id, sp1, sp2, sp3
`

type UpsertSPSettingsParams struct {
	SchoolID       int64 `json:"school_id"`
	AcademicYearID int64 `json:"academic_year_id"`
	Sp1            int32 `json:"sp1"`
	Sp2            int32 `json:"sp2"`
	Sp3            int32 `json:"sp3"`
}

func (q *Queries) UpsertSPSettings(ctx context.Context, arg UpsertSPSettingsParams) (DisciplineSpSetting, error) {
	row := q.db.QueryRow(ctx, upsertSPSettings,
		arg.SchoolID,
		arg.AcademicYearID,
		arg.Sp1,
		arg.Sp2,
		arg.Sp3,
	)
	var i DisciplineSpSetting
	err := row.Scan(
		&i.SchoolID,
		&i.AcademicYearID,
		&i.Sp1,
		&i.Sp2,
		&i.Sp3,
	)
	return i, err
}
